import{_ as a,C as t,o as i,c as s,E as n,a2 as d}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/verification-evidence-20260909/output-is-not-effect-figure.en.svg",y=JSON.parse('{"title":"The Tool Result Was Blocked. Why Had the Operation Already Run?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Tool Result Was Blocked. Why Had the Operation Already Run?","date":"2026-09-09","published_date":"2026-09-09","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","research_question":"The Tool Result Was Blocked. Why Had the Operation Already Run?","summary":"An upstream middleware experiment produced executed and blocked receipts for one call. Output withholding and execution prevention describe different stages.","cover":"/assets/verification-evidence-20260909/03-output-is-not-effect.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments; not independent QA; dependency substitutions disclosed","pageClass":"verification-evidence-article","sources":["https://github.com/ag2ai/ag2/pull/3240"]},"headers":[],"relativePath":"en/engineering/2026-09-09-output-is-not-effect.md","filePath":"en/engineering/2026-09-09-output-is-not-effect.md","lastUpdated":1788930481000}'),l={name:"en/engineering/2026-09-09-output-is-not-effect.md"};function u(h,e,p,g,m,f){const r=t("ArticleCover"),o=t("ArticleTableScroll");return i(),s("div",null,[n(r,{image:"/assets/verification-evidence-20260909/03-output-is-not-effect.png",kicker:"Engineering · Experimental research",title:"The Tool Result Was Blocked. Why Had the Operation Already Run?",summary:"An upstream middleware experiment produced executed and blocked receipts for one call. Output withholding and execution prevention describe different stages.",version:"2026-09-09",languageHref:"/zh/engineering/2026-09-09-output-is-not-effect",languageLabel:"中文"}),n(o,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-tool-result-was-blocked-why-had-the-operation-already-run" tabindex="-1">The Tool Result Was Blocked. Why Had the Operation Already Run? <a class="header-anchor" href="#the-tool-result-was-blocked-why-had-the-operation-already-run" aria-label="Permalink to &quot;The Tool Result Was Blocked. Why Had the Operation Already Run?&quot;">​</a></h1><p>One tool call produced an <code>executed</code> receipt followed by a <code>blocked</code> receipt. A screen showing only the last word could suggest that nothing happened.</p><p>Our fixture&#39;s counter said otherwise: the tool ran once. Its returned content was withheld afterward.</p><p>There is no contradiction. “Blocked” needs an object: the call, the returned information, or subsequent processing. Compressing these into one overall status can erase precisely the detail that governance added.</p><h2 id="permission-to-call-is-not-permission-to-disclose" tabindex="-1">Permission to call is not permission to disclose <a class="header-anchor" href="#permission-to-call-is-not-permission-to-disclose" aria-label="Permalink to &quot;Permission to call is not permission to disclose&quot;">​</a></h2><p>AG2 is an open-source agent application framework. <a href="https://github.com/ag2ai/ag2/pull/3240" target="_blank" rel="noreferrer">PR #3240</a> proposes scanning tool output because an authorized call can still return sensitive information. Input checks cannot inspect data that has not yet been returned.</p><p>We fixed the then-unmerged commit <code>bf363ef52853e7b918863dec2fe1e3902b811e6f</code> and exercised its original middleware entry point. Sensitive-looking strings came from public test fixtures, not credentials.</p><p>In the enforced secret case, the tool counter reached one, the result became a governance error, and the returned object no longer contained the fixture secret. Receipts recorded execution and subsequent withholding.</p><p>That establishes behavior at this middleware boundary. The tool was a counter fixture; no business write, network effect, or actual model-context ingestion was tested.</p><h2 id="modes-and-containers-change-the-boundary" tabindex="-1">Modes and containers change the boundary <a class="header-anchor" href="#modes-and-containers-change-the-boundary" aria-label="Permalink to &quot;Modes and containers change the boundary&quot;">​</a></h2><p>We retained the upstream policy, scanning, rewriting, and receipt logic while replacing framework event shells. Every case passed through the original <code>on_tool_execution</code>; two independent processes produced the same observations.</p><table tabindex="0"><thead><tr><th>Condition</th><th style="text-align:right;">Tool executions</th><th>Fixture content in returned object</th><th>Receipt sequence</th></tr></thead><tbody><tr><td>ENFORCE, successful secret text</td><td style="text-align:right;">1</td><td>Withheld</td><td>executed → blocked</td></tr><tr><td>MONITOR, same text</td><td style="text-align:right;">1</td><td>Redacted</td><td>executed → executed</td></tr><tr><td>OBSERVE, same text</td><td style="text-align:right;">1</td><td>Preserved</td><td>executed</td></tr><tr><td>ENFORCE, secret in error object</td><td style="text-align:right;">1</td><td>Preserved</td><td>error</td></tr><tr><td>FLAG policy</td><td style="text-align:right;">1</td><td>Preserved, finding recorded</td><td>executed → executed</td></tr><tr><td>Secret in structured value</td><td style="text-align:right;">1</td><td>Withheld</td><td>executed → blocked</td></tr><tr><td>Secret in structured key</td><td style="text-align:right;">1</td><td>Preserved</td><td>executed</td></tr><tr><td>SSN in structured string value</td><td style="text-align:right;">1</td><td>Redacted</td><td>executed → executed</td></tr></tbody></table><p><img src="'+c+'" alt="Figure: schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence."></p><p><em>Figure 1. schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence.</em></p><p>OBSERVE and FLAG are explicit policy choices, not bypass discoveries. MONITOR converts a blocking finding into redaction, so “not enforced” does not always mean “untouched.”</p><h2 id="an-error-is-another-output-path" tabindex="-1">An error is another output path <a class="header-anchor" href="#an-error-is-another-output-path" aria-label="Permalink to &quot;An error is another output path&quot;">​</a></h2><p>The original code scans successful text parts and structured string values. It returns error objects directly. Its mapping traversal visits values, not keys.</p><p>The same fixture secret therefore receives different treatment when moved from successful text into an error object or dictionary key. That establishes scan coverage, not confirmed leakage into a real model: other framework stages might serialize, sanitize, or restrict these objects.</p><p>A useful review matrix names the containers and modes explicitly. Otherwise a successful text test can quietly become an unsupported claim about every return path.</p><h2 id="receipts-need-a-stage" tabindex="-1">Receipts need a stage <a class="header-anchor" href="#receipts-need-a-stage" aria-label="Permalink to &quot;Receipts need a stage&quot;">​</a></h2><p>The sequence <code>executed → blocked</code> accurately describes an executed tool whose result was withheld. A consumer that treats the final receipt as the whole action&#39;s status loses this distinction.</p><p>Conversely, <code>executed → executed</code> need not mean two executions. In our monitor and flag cases the counter remained one; the second receipt described output governance.</p><p>Receipt counts are not tool counts. A clearer representation would identify the call, the recorded stage, whether execution occurred, and whether returned information was permitted onward. This is a design recommendation, not an implemented universal receipt contract.</p><p>For a real effectful tool, withheld output would not undo the effect. That is an inference from the ordering, not a business transaction reproduced here. Whether to retry must depend on the operation&#39;s own identity, reconciliation, or idempotency contract.</p><p>The <a href="https://joinwell52-ai.github.io/joinwell52/en/research/evidence/2026-09-09-verification-evidence" target="_blank" rel="noreferrer">evidence guide</a> preserves eight cases and the precise substitution boundary. Actual Agent integration, message serialization, model ingestion, and external effects remain untested.</p><p>The input boundary decides whether a tool may act. The output boundary decides what information may continue after it acts. Both matter because they answer different questions.</p>',26))])}const x=a(l,[["render",u]]);export{y as __pageData,x as default};
